#!/usr/bin/env python3
"""wubu_online_brain.py -- WuBuDesk cohost ONLINE brain (OpenAI-compatible proxy).

Sits locally as an OpenAI-compatible /v1/chat/completions server so the existing
cohost loop (wubudesk_loop.py -> BRAIN env) can talk to a REAL online model
without changing the loop. Routes to the free tiers the boss authorized:
  * NVIDIA nemotron-3-super-120b-a12b  (integrate.api.nvidia.com, NVIDIA_API_KEY)
  * Nous portal free API               (NOUS-managed key, provider=nous)

Why: the local :57064 was serving a tiny ollama model. For the live stream the
cohost needs a real brain. We properly make it: a tiny self-hosted proxy, no
third-party cohost service. C11-port spirit -> keep it small and self-contained.

License: SPDX-License-Identifier: WaefreBeorn-UMV3
"""
import os, json, urllib.request, threading
from http.server import BaseHTTPRequestHandler, HTTPServer

ENV = r"C:\Users\eman5\AppData\Local\hermes\profiles\wubudesk\.env"

def _load_env():
    d = {}
    try:
        for line in open(ENV):
            line = line.strip()
            if not line or line.startswith("#") or "=" not in line:
                continue
            k, v = line.split("=", 1)
            d[k.strip()] = v.strip()
    except Exception:
        pass
    return d

ENVV = _load_env()
NVIDIA_KEY = ENVV.get("NVIDIA_API_KEY", "")
# Nous key (if present in the same .env); Nous portal is also the agent default.
NOUS_KEY = ENVV.get("NOUS_API_KEY", ENVV.get("OPENROUTER_API_KEY", ""))

PORT = int(os.environ.get("WUBU_BRAIN_PORT", "57065"))
NVIDIA_URL = "https://integrate.api.nvidia.com/v1/chat/completions"
NVIDIA_MODEL = "nvidia/nemotron-3-super-120b-a12b"

# Nous free portal: the agent already routes via provider=nous / tencent/hy3:free.
# We expose it here too so the cohost has a second online path.
NOUS_URL = "https://inference.nousresearch.com/v1/chat/completions"


def _post(url, headers, payload):
    data = json.dumps(payload).encode()
    req = urllib.request.Request(url, data=data, headers=headers, method="POST")
    with urllib.request.urlopen(req, timeout=60) as r:
        return r.read().decode()


def chat(messages, temperature=0.4, max_tokens=180):
    # NVIDIA nemotron free endpoint is TEXT-ONLY. The cohost loop may send
    # vision messages (image_url). Strip image parts so the text model gets
    # clean text (the loop's local :57064 brain handles true multimodal).
    clean = []
    for m in messages:
        content = m.get("content")
        if isinstance(content, list):
            text = " ".join(p.get("text", "") for p in content
                            if isinstance(p, dict) and p.get("type") == "text")
            clean.append({"role": m.get("role", "user"), "content": text})
        else:
            clean.append({"role": m.get("role", "user"), "content": content or ""})
    payload = {"model": NVIDIA_MODEL, "messages": clean,
               "temperature": temperature, "max_tokens": max_tokens, "stream": False}
    hdrs = {"Authorization": f"Bearer {NVIDIA_KEY}",
            "Content-Type": "application/json"}
    try:
        raw = _post(NVIDIA_URL, hdrs, payload)
        return json.loads(raw)["choices"][0]["message"]["content"]
    except Exception as e:
        if NOUS_KEY:
            try:
                p2 = dict(payload); p2["model"] = "tencent/hy3:free"
                h2 = {"Authorization": f"Bearer {NOUS_KEY}",
                      "Content-Type": "application/json"}
                raw = _post(NOUS_URL, h2, p2)
                return json.loads(raw)["choices"][0]["message"]["content"]
            except Exception:
                pass
        return f"[brain-offline:{e}]"


class H(BaseHTTPRequestHandler):
    def _send(self, obj, code=200):
        body = json.dumps(obj).encode()
        self.send_response(code)
        self.send_header("Content-Type", "application/json")
        self.send_header("Access-Control-Allow-Origin", "*")
        self.end_headers()
        self.wfile.write(body)

    def do_OPTIONS(self):
        self.send_response(204)
        self.send_header("Access-Control-Allow-Origin", "*")
        self.send_header("Access-Control-Allow-Headers", "*")
        self.end_headers()

    def do_POST(self):
        if self.path.rstrip("/") not in ("/v1/chat/completions", "/chat/completions"):
            self._send({"error": "not found"}, 404); return
        try:
            ln = int(self.headers.get("Content-Length", 0))
            req = json.loads(self.rfile.read(ln))
        except Exception as e:
            self._send({"error": str(e)}, 400); return
        msgs = req.get("messages", [])
        temp = float(req.get("temperature", 0.4))
        mt = int(req.get("max_tokens", 180))
        text = chat(msgs, temperature=temp, max_tokens=mt)
        self._send({
            "id": "wubu-online", "object": "chat.completion", "model": NVIDIA_MODEL,
            "choices": [{"index": 0, "finish_reason": "stop",
                         "message": {"role": "assistant", "content": text}}],
            "usage": {"prompt_tokens": 0, "completion_tokens": 0, "total_tokens": 0}
        })

    def log_message(self, *a):
        pass


if __name__ == "__main__":
    srv = HTTPServer(("127.0.0.1", PORT), H)
    print(f"[wubu_online_brain] listening on 127.0.0.1:{PORT} (NVIDIA free + Nous fallback)")
    srv.serve_forever()

#!/usr/bin/env python3
"""wubu_obs.py — WuBuDesk OBS cohost controller ("face + hands" on the stream).

This is the Windows-side AGI's interface to OBS Studio via obs-websocket 5.x.
It gives WuBuDesk:
  * HANDS  — scene/source control (switch scenes, toggle/mute sources, set
             text, move/resize, trigger hotkeys, start/stop stream/record).
  * FACE   — a managed "avatar" browser source (the cohost's face) that we
             can point at an overlay page and push state into (mood, speak).

Design: self-contained, depends only on `websocket-client` (+ stdlib). No
monolithic God-object — a thin client plus a small command surface so other
agents (on WSL/remote) can drive OBS through WuBuDesk over the cluster channel.

Auth: obs-websocket 5 uses a salted SHA256 challenge:
  secret = SHA256(password + salt)
  auth   = base64( SHA256(secret + challenge) + salt )   (legacy variant)
  (This client implements both the v5 "challenge" and legacy "auth" fields.)

Use:
  from wubu_obs import ObsCohost
  obs = ObsCohost(host="localhost", port=4455, password="...")
  obs.connect()
  obs.set_scene("Starting Soon")
  obs.set_source_text("CohostTicker", "Yo chat, WuBu online.")
  obs.speak("happy", "Yo chat, WuBu online.")  # updates the avatar face source

License: SPDX-License-Identifier: WaefreBeorn-UMV3
"""
import base64
import hashlib
import json
import os
import sys
import time

try:
    import websocket
except ImportError:
    sys.stderr.write("FATAL: pip install websocket-client\n")
    raise


class ObsError(RuntimeError):
    pass


class ObsCohost:
    """OBS websocket 5.x client with reconnection and event support.

    Thread-safe via a single lock around send/recv — OBS serialises
    requests on its end anyway, so concurrent Python calls just queue.
    """

    def __init__(self, host="localhost", port=4455, password=None,
                 avatar_source="WuBuFace", face_url=None, timeout=8.0,
                 max_retries=3, retry_delay=1.5):
        self.url = f"ws://{host}:{port}"
        self.password = password
        self.avatar_source = avatar_source
        self.face_url = face_url
        self.timeout = timeout
        self.max_retries = max_retries
        self.retry_delay = retry_delay
        self._ws = None
        self._msg_id = 0
        self._op = None  # negotiated RPC version
        self._event_cb = None  # callback: event_type -> dict
        self._connected = False
        self.last_event = None
        self._lock = __import__("threading").Lock()

    # -- context manager ----------------------------------------------------
    def __enter__(self):
        self.connect()
        return self

    def __exit__(self, *exc):
        self.close()
        return False

    # ---- low level ----
    def _next_id(self):
        self._msg_id += 1
        return f"wubu-{self._msg_id}"

    def _send(self, op, payload):
        with self._lock:
            self._ws.send(json.dumps({"op": op, "d": payload}))

    def _recv(self, want_id):
        deadline = time.time() + self.timeout
        while time.time() < deadline:
            raw = self._ws.recv()
            if raw is None:
                continue
            msg = json.loads(raw)
            op = msg.get("op")
            if op == 5:  # Event
                self._on_event(msg.get("d", {}))
                continue
            d = msg.get("d", {})
            if d.get("requestId") == want_id or op == 2:
                return msg
        raise ObsError("timeout waiting for response")

    def _on_event(self, d):
        """Store the last event and dispatch to subscriber callback."""
        self.last_event = d
        if self._event_cb:
            try:
                self._event_cb(d.get("eventType", ""), d)
            except Exception:
                pass

    def _call(self, req_type, **params):
        """Send a request with retry on transient errors.

        Retries on timeout/connection errors up to max_retries times with
        exponential backoff. Reconnects if the socket died.
        """
        last = None
        for attempt in range(self.max_retries + 1):
            try:
                if not self._ws:
                    if not self._reconnect():
                        raise ObsError("not connected and reconnect failed")
                rid = self._next_id()
                self._send(6, {  # Request
                    "requestType": req_type,
                    "requestId": rid,
                    "requestData": params,
                })
                msg = self._recv(rid)
                d = msg.get("d", {})
                if msg.get("op") == 7:  # RequestResponse
                    rs = d.get("requestStatus", {})
                    if rs.get("result") is False:
                        code = rs.get("code")
                        comment = rs.get("comment")
                        err = ObsError(f"{req_type} failed [{code}]: {comment}")
                        last = err
                        # 502/503 = transient, retry; others are permanent
                        if code in ("websocketUnavailable", "invalidRequestType",
                                     "unsupportedRequest", "invalidRequestData",
                                     "unauthorized", "invalidsettings",
                                     "generic", "unknown"):
                            raise err
                        continue  # retry
                    return d.get("responseData", {})
                return d
            except ObsError as e:
                last = e
                if "timeout" in str(e).lower() or "not connected" in str(e).lower():
                    if not self._reconnect():
                        pass  # keep retrying
                continue
            except Exception as e:
                last = e
                continue
            time.sleep(self.retry_delay * (attempt + 1))
        raise last or ObsError(f"{req_type} failed after {self.max_retries} retries")

    # ---- connection + auth ----
    def _reconnect(self):
        """Attempt to re-establish the OBS websocket connection."""
        self.close()
        for attempt in range(self.max_retries):
            try:
                self._ws = websocket.create_connection(self.url, timeout=self.timeout)
                hello = json.loads(self._ws.recv())
                if hello.get("op") != 0:  # Hello
                    raise ObsError("expected Hello")
                self._op = hello["d"].get("rpcVersion", 1)
                auth = hello["d"].get("authentication")
                payload = {"rpcVersion": self._op}
                if auth:
                    if not self.password:
                        raise ObsError("server requires auth; password missing")
                    payload["authentication"] = self._make_auth(self.password,
                                                                auth["salt"],
                                                                auth["challenge"])
                self._send(1, payload)  # Identify
                ident = json.loads(self._ws.recv())
                if ident.get("op") != 2:
                    raise ObsError("expected Identified")
                if not ident["d"].get("negotiatedRpcVersion"):
                    raise ObsError("identify rejected: %s" % ident["d"].get("reason"))
                self._connected = True
                return True
            except Exception as e:
                self._connected = False
                self._ws = None
                if attempt < self.max_retries - 1:
                    time.sleep(self.retry_delay * (attempt + 1))
        return False

    def connect(self):
        """Connect (or reconnect) to OBS. Idempotent."""
        if self._connected and self._ws:
            return True
        return self._reconnect()

    @staticmethod
    def _make_auth(password, salt, challenge):
        """obs-websocket v5 authentication (per official spec)."""
        secret = base64.b64encode(
            hashlib.sha256((password + salt).encode()).digest()).decode()
        auth = base64.b64encode(
            hashlib.sha256((secret + challenge).encode()).digest()).decode()
        return auth

    def close(self):
        self._connected = False
        if self._ws:
            try:
                self._ws.close()
            finally:
                self._ws = None

    def on_event(self, callback):
        """Subscribe to OBS events (scene change, recording start/stop, etc.).

        callback(eventType, eventData) -> None
        """
        self._event_cb = callback

    def is_streaming(self):
        """Return True if OBS is currently streaming."""
        try:
            d = self._call("GetStreamingStatus")
            return d.get("outputActive", False)
        except Exception:
            return False

    def is_recording(self):
        """Return True if OBS is currently recording."""
        try:
            d = self._call("GetRecordingStatus")
            return d.get("recording", False)
        except Exception:
            return False

    # ---- HANDS: scene + source control ----
    def get_version(self):
        return self._call("GetVersion")

    def list_scenes(self):
        data = self._call("GetSceneList")
        return [s["sceneName"] for s in data.get("scenes", [])]

    def get_current_scene(self):
        return self._call("GetCurrentProgramScene").get("currentProgramSceneName", "")

    def set_scene(self, name, transition="Cut", duration=0):
        """Switch to scene with optional transition."""
        if transition == "Cut":
            return self._call("SetCurrentProgramScene", sceneName=name)
        else:
            return self._call("SetCurrentProgramScene", sceneName=name,
                              transitionName=transition,
                              transitionDuration=int(duration * 1000))

    def list_inputs(self, scene=None):
        if scene:
            data = self._call("GetSceneItemList", sceneName=scene)
            return [it["sourceName"] for it in data.get("sceneItems", [])]
        data = self._call("GetInputList")
        return [i["inputName"] for i in data.get("inputs", [])]

    def set_source_text(self, source, text):
        """Set text on a text source (browser/text input)."""
        try:
            return self._call("SetInputSettings", inputName=source,
                              inputSettings={"text": text}, overlay=True)
        except ObsError:
            return self._call("SetInputSettings", inputName=source,
                              inputSettings={"message": text}, overlay=True)

    def set_source_texts(self, pairs):
        """Batch-set text on multiple sources. Each item: (source, text)."""
        results = []
        for src, txt in pairs:
            results.append((src, self.set_source_text(src, txt)))
        return results

    def toggle_source(self, source, visible=None):
        scene = self.get_current_scene()
        items = self._call("GetSceneItemList", sceneName=scene).get("sceneItems", [])
        item = next((i for i in items if i.get("sourceName") == source), None)
        if not item:
            raise ObsError(f"source {source!r} not in scene {scene!r}")
        if visible is None:
            cur = item.get("sceneItemEnabled", True)
            visible = not cur
        self._call("SetSceneItemEnabled", sceneName=scene,
                   sceneItemId=item["sceneItemId"],
                   sceneItemEnabled=bool(visible))
        return visible

    def toggle_sources(self, sources, visible=None):
        """Batch-toggle multiple sources. Returns dict of name -> bool."""
        return {s: self.toggle_source(s, visible) for s in sources}

    def set_source_transform(self, source, **transform):
        """Set position/scale/rotation for a scene item.

        Args: positionX, positionY, scaleX, scaleY, rotation, etc.
        """
        scene = self.get_current_scene()
        items = self._call("GetSceneItemList", sceneName=scene).get("sceneItems", [])
        item = next((i for i in items if i.get("sourceName") == source), None)
        if not item:
            raise ObsError(f"source {source!r} not in scene {scene!r}")
        t = (item.get("sceneItemTransform") or {}).copy()
        t.update(transform)
        return self._call("SetSceneItemTransform", sceneName=scene,
                          sceneItemId=item["sceneItemId"],
                          sceneItemTransform=t)

    def mute_source(self, source, muted=None):
        cur = self._call("GetInputMute", inputName=source).get("inputMuted", False)
        if muted is None:
            muted = not cur
        self._call("SetInputMute", inputName=source, inputMuted=bool(muted))
        return muted

    def set_source_volume(self, source, db=None, mul=None):
        """Set volume for an audio source. db = dB, mul = multiplier (0..1)."""
        return self._call("SetInputVolume", inputName=source,
                          inputVolumeDb=db, inputVolumeMul=mul)

    def get_source_volume(self, source):
        d = self._call("GetInputVolume", inputName=source)
        return d.get("inputVolumeDb"), d.get("inputVolumeMul")

    def trigger_hotkey(self, name):
        """Trigger a saved hotkey by name."""
        return self._call("TriggerHotkeyByName", hotkeyName=name)

    def get_source_audio_db(self, source):
        """Get current audio peak level for an input (for metering)."""
        try:
            d = self._call("GetInputAudioDB", inputName=source)
            return d.get("inputAvgDB"), d.get("inputPeakDB")
        except Exception:
            return None, None

    def start_stream(self):
        return self._call("StartStream")

    def stop_stream(self):
        return self._call("StopStream")

    def start_record(self):
        return self._call("StartRecord")

    def stop_record(self):
        return self._call("StopRecord")

    def start_replay_buffer(self):
        return self._call("StartRecordDirectory")

    def save_replay_buffer(self):
        return self._call("SaveRecordDirectory")

    def start_virtual_cam(self):
        return self._call("StartVirtualCam")

    def stop_virtual_cam(self):
        return self._call("StopVirtualCam")

    def take_screenshot(self, source=None, width=1920, height=1080,
                        format="png", output_path=None):
        """Capture a screenshot via OBS (uses source or entire canvas)."""
        kwargs = {"ImageSize": {"width": width, "height": height},
                  "CompressionRatio": 100}
        if source:
            kwargs["SourceName"] = source
        if output_path:
            kwargs["OutputUrl"] = output_path
        return self._call("TakeSourceScreenshot", **kwargs)

    # ---- FACE: avatar source management ----
    def ensure_face(self, url=None):
        """Point the avatar browser source (the cohost's face) at `url`."""
        url = url or self.face_url
        if not url:
            return None
        try:
            return self._call("SetInputSettings", inputName=self.avatar_source,
                              inputSettings={"url": url, "width": 1920, "height": 1080,
                                             "fps": 30, "reroute_audio": False},
                              overlay=True)
        except ObsError as e:
            return {"warn": str(e)}

    def speak(self, mood="neutral", text=None, mode="live"):
        """Push cohost state into the face overlay via a local state file the
        browser source polls. Decouples WuBuDesk from OBS render timing.

        mode: "live" (stream overlay) or "movie" (recorded avatar).
        The state file lives in the face/ directory so the browser source
        can fetch it over localhost:8137 or via file:// access.

        Uses atomic write (os.replace) so the overlay never reads a
        half-written JSON file — critical because the browser source polls
        this file ~2-4 times per second while the cohost thread may be
        writing a new state concurrently.
        """
        # speak_ms = estimated speech-bubble duration in ms (overlay uses
        # this to animate lip-sync + hide the bubble). Match wubu_cohost.say().
        text_len = len(text or "")
        speak_ms = max(1400, min(9000, text_len * 55))
        state = {
            "mood": mood,
            "text": text,
            "speaking": bool(text),
            "speak_ms": speak_ms,
            "ts": time.time(),
            "mode": mode,
        }
        face_dir = os.environ.get("WUBU_FACE_DIR",
                                   r"C:/Users/eman5/WuBuMedia/face")
        face_path = os.path.join(face_dir, "face_state.json")
        try:
            os.makedirs(face_dir, exist_ok=True)
            tmp = face_path + ".tmp"
            with open(tmp, "w") as f:
                json.dump(state, f)
            os.replace(tmp, face_path)  # atomic: overlay never reads half-written JSON
        except OSError:
            pass
        return state


def main():
    pw = os.environ.get("OBS_WS_PASSWORD")
    if not pw:
        try:
            cfg = json.load(open(os.path.join(
                os.environ.get("APPDATA", r"C:\Users\eman5\AppData\Roaming"),
                "obs-studio", "plugin_config", "obs-websocket", "config.json")))
            pw = cfg.get("server_password")
        except Exception:
            pw = None
    obs = ObsCohost(port=4455, password=pw)
    try:
        obs.connect()
        v = obs.get_version()
        print("CONNECTED")
        print("obsVersion:", v.get("obsVersion"))
        print("rpcVersion:", v.get("rpcVersion"))
        print("scenes:", obs.list_scenes())
        print("current:", obs.get_current_scene())
        print("streaming:", obs.is_streaming())
        print("recording:", obs.is_recording())
    except ObsError as e:
        print("OBS-ERR:", e)
        sys.exit(1)
    finally:
        obs.close()


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
# SPDX-License-Identifier: WaefreBeorn-UMV3
"""wubu_agent.py — The cohost's "hands and eyes" on the system.

Phase 4: AGI Master Computer Control.

This is what makes the cohost a real agent instead of a reactive plugin.
It lets the cohost:
  * Read system stats (CPU, GPU, memory, OBS state) — context for replies
  * Switch OBS scenes, mute sources, toggle recording/streaming
  * Trigger hotkeys to control the desktop (launch games, switch windows)
  * Read the screen via wubu_desktop + wubu_vision
  * Respond to global hotkeys (Ctrl+Alt+Chat triggers a cohost response)

Design principles:
  * Graceful everywhere — every function returns a default, never raises
    into the live loop. If the system call fails, the cohost still works.
  * Lazy imports — torch, psutil, keyboard only loaded when needed
  * No secrets logged — GPU names and stats only, never file paths of secrets

Usage:
  from wubu_agent import Agent
  agent = Agent(obs)  # obs = wubu_obs.ObsCohost() or wubu_stage.connect()
  agent.stats()       # -> dict of CPU/GPU/memory/OBS
  agent.mute_game()   # duck desktop audio
  agent.switch_scene("Gaming")
  agent.screenshot()  # -> PNG path

License: SPDX-License-Identifier: WaefreBeorn-UMV3
"""
import os
import sys
import time

# Reuse existing modules
HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, HERE)

try:
    import wubu_desktop  # C11 wubucmd.exe + PowerShell fallback
    _HAS_DESKTOP = True
except Exception:
    _HAS_DESKTOP = False


def stats():
    """Gather system stats: CPU, GPU, memory, OBS state.

    All values are sampled once; no persistent monitoring. Returns a dict
    suitable for including in the face overlay HUD. Returns {} on any failure.

    Research: psutil for cross-platform stats, pynvml for NVIDIA GPU.
    We use lazy imports so psutil/pynvml are optional — degrades gracefully.
    """
    out = {}

    # CPU %
    try:
        import psutil
        out["cpu"] = round(psutil.cpu_percent(interval=0.2), 1)
        mem = psutil.virtual_memory()
        out["mem_pct"] = round(mem.percent, 1)
        out["mem_gb"] = round(mem.used / (1024**3), 2)
    except Exception:
        out["cpu"] = "n/a"

    # GPU stats (NVIDIA only — the rig has an RTX 2080 SUPER)
    try:
        import pynvml
        pynvml.nvmlInit()
        handle = pynvml.nvmlDeviceGetHandleByIndex(0)
        util = pynvml.nvmlDeviceGetUtilization(handle)
        out["gpu_util"] = util.gpu
        out["gpu_mem"] = util.memory
        # GPU temperature
        try:
            temp = pynvml.nvmlDeviceGetTemperature(handle, pynvml.NVML_TEMPERATURE_GPU)
            out["gpu_temp"] = temp
        except Exception:
            pass
        # GPU name
        try:
            name = pynvml.nvmlDeviceGetName(handle)
            if isinstance(name, bytes):
                name = name.decode()
            out["gpu_name"] = name
        except Exception:
            pass
        pynvml.nvmlShutdown()
    except Exception:
        pass  # pynvml not installed or no NVIDIA GPU

    return out


def screenshot(path=None):
    """Take a screenshot of the primary display.

    Returns path to PNG file. Uses wubu_desktop.screenshot() which prefers
    the native C11 wubucmd.exe and falls back to PowerShell.
    """
    if _HAS_DESKTOP:
        try:
            return wubu_desktop.screenshot(path)
        except Exception as e:
            print(f"[agent] screenshot failed: {e}", file=sys.stderr)
    # Fallback: PIL ImageGrab
    try:
        from PIL import ImageGrab
        return ImageGrab.grab().save(path or "screenshot.png")
    except Exception:
        return None


def list_windows():
    """List all visible windows. Returns list of titles or [] on failure."""
    if _HAS_DESKTOP:
        try:
            return wubu_desktop.list_windows()
        except Exception:
            pass
    return []


def focus_window(substr):
    """Focus the first window whose title contains substr."""
    if _HAS_DESKTOP:
        try:
            return wubu_desktop.focus_window(substr)
        except Exception as e:
            print(f"[agent] focus failed: {e}", file=sys.stderr)
    return None


class Agent:
    """High-level control of the OBS + desktop.

    Wraps wubu_stage.wubu_stage (for OBS) and wubu_desktop (for Windows)
    into a single 'master AGI' interface that the cohost loop can query.

    All methods degrade gracefully — if OBS isn't connected, they return
    False/None/empty rather than raising.
    """

    def __init__(self, obs=None):
        self.obs = obs  # wubu_obs.ObsCohost or None
        self._stats_cache = None
        self._stats_ts = 0

    # -- OBS integration ----------------------------------------------------
    def mute_source(self, source, muted=True):
        """Mute/unmute an audio source in OBS."""
        if not self.obs:
            return False
        try:
            self.obs._call("SetSourceRender", sourceName=source,
                           render=not muted)
            return True
        except Exception:
            return False

    def mute_game(self, muted=True):
        """Mute desktop/game audio in OBS."""
        # The source name varies; try common ones
        for name in ("Desktop Audio", "Game Capture", "Audio Output Capture"):
            if self.mute_source(name, muted):
                return True
        return False

    def switch_scene(self, scene_name):
        """Switch to a named OBS scene."""
        if not self.obs:
            return False
        try:
            self.obs._call("SetCurrentProgramScene", sceneName=scene_name)
            return True
        except Exception:
            return False

    def list_scenes(self):
        """Return list of OBS scene names."""
        if not self.obs:
            return []
        try:
            scenes = self.obs._call("GetSceneList")
            return [s.get("name", "") for s in scenes.get("scenes", [])]
        except Exception:
            return []

    def start_recording(self):
        """Start OBS recording."""
        if not self.obs:
            return False
        try:
            self.obs._call("StartRecord")
            return True
        except Exception:
            return False

    def stop_recording(self):
        """Stop OBS recording."""
        if not self.obs:
            return False
        try:
            self.obs._call("StopRecord")
            return True
        except Exception:
            return False

    def toggle_stream(self):
        """Start or stop streaming (toggles)."""
        if not self.obs:
            return False
        try:
            status = self.obs._call("GetRecordStatus")
            if status.get("recording"):
                self.obs._call("StopStream")
            else:
                self.obs._call("StartStream")
            return True
        except Exception:
            return False

    def current_scene(self):
        """Return the name of the current OBS scene."""
        if not self.obs:
            return ""
        try:
            return self.obs._call("GetCurrentProgramScene").get("sceneName", "")
        except Exception:
            return ""

    # -- System stats -------------------------------------------------------
    def stats(self, cached=True):
        """Return system stats (cached for 2s to avoid hammering psutil)."""
        if cached and time.time() - self._stats_ts < 2:
            return self._stats_cache or {}
        s = stats()
        s["obs"] = bool(self.obs)
        try:
            s["obs_scene"] = self.current_scene()
        except Exception:
            pass
        self._stats_cache = s
        self._stats_ts = time.time()
        return s

    # -- Desktop control ----------------------------------------------------
    def see(self, prompt, max_tokens=120):
        """Take a screenshot and ask the vision model what's on it."""
        path = screenshot()
        if not path:
            return "I can't see the screen right now."
        try:
            import wubu_vision
            return wubu_vision.see(path, prompt, max_tokens=max_tokens) or ""
        except Exception:
            return ""

    def activate_window(self, substr):
        """Activate (foreground) a window by title substring."""
        return focus_window(substr)


# -- Global hotkey listener -----------------------------------------------
# Research: 'keyboard' library (boppreh) provides global keyboard hooks on
# Windows without admin privileges. We use Ctrl+Alt+B (Boss) to wake the
# cohost — it's unlikely to conflict with games or OBS.
def register_hotkeys(callback, hotkeys=None):
    """Register global hotkeys that trigger callback(action) when pressed.

    Args:
        callback: function(action) called when a hotkey fires
        hotkeys: dict of {hotkey_string: action_name}
                e.g. {"ctrl+alt+b": "wake", "ctrl+alt+p": "poke"}
                Returns True if registered, False if 'keyboard' lib unavailable.

    The 'keyboard' library requires no admin on Windows for global hooks,
    but may need to run in the main thread.
    """
    if hotkeys is None:
        hotkeys = {"ctrl+alt+b": "wake", "ctrl+alt+p": "poke"}
    try:
        import keyboard
        for hk, action in hotkeys.items():
            keyboard.add_hotkey(hk, callback, args=(action,),
                                suppress=False)  # don't suppress — let games use it
        return True
    except ImportError:
        print("[agent] 'keyboard' library not installed; hotkeys disabled",
              file=sys.stderr)
        return False
    except Exception as e:
        print(f"[agent] hotkey registration failed: {e}", file=sys.stderr)
        return False


if __name__ == "__main__":
    # Self-test: gather and print system stats
    s = stats()
    print("System stats:")
    for k, v in s.items():
        print(f"  {k}: {v}")
    print(f"\nVisible windows: {list_windows()[:5]}")
    print(f"Desktop module available: {_HAS_DESKTOP}")

